sql.20261230010000_ranni_souhrn_a_push_pri_o:
-- 🔔 Ranní souhrnný push + dedup pro push u nové WhatsApp objednávky.
--
-- Návrh (docs/30-navrhu-2026-09-10.md, body 16+17): appka umí detekovat
-- výčepy po termínu (lib/vycepyVenku.ts) i čekající WhatsApp zprávy
-- (fetchPendingWhatsAppCount), ale obojí se ukáže jen tomu, kdo si appku
-- otevře. Push u NOVÉ WhatsApp objednávky (bod 15) posílá přímo edge funkce
-- whatsapp-webhook při uložení zprávy — to je vždy jednorázová událost.
-- „Výčep po termínu" ale žádnou vlastní chvíli „teď se to stalo" nemá (je to
-- stav, ne událost) — nedává smysl na něj čekat okamžitou notifikací, jde ho
-- jen pravidelně kontrolovat. Proto 16 a 17 spojené do JEDNOHO denního
-- souhrnu, který pošle obojí najednou.
--
-- Volá se stejným vzorem jako trigger_whatsapp_auto_parse (migrace
-- 20261121000000): pg_net → edge funkce posli-push, ověřeno sdíleným
-- interním secretem z app_secrets (X-Internal-Cron-Secret), který
-- _shared/require-user.ts už umí ověřit — posli-push tedy nepotřebuje
-- žádnou úpravu.

CREATE EXTENSION IF NOT EXISTS pg_net WITH SCHEMA extensions;

CREATE OR REPLACE FUNCTION public.posli_ranni_souhrn()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_secret text;
  v_whatsapp_cekajici int;
  v_vycepy_po_terminu int;
  v_kauce_czk numeric;
  v_radky text[] := ARRAY[]::text[];
  v_telo text;
BEGIN
  SELECT value INTO v_secret FROM app_secrets WHERE key = 'WHATSAPP_CRON_SECRET';
  IF v_secret IS NULL THEN
    RETURN;
  END IF;

  SELECT count(*) INTO v_whatsapp_cekajici
  FROM whatsapp_incoming
  WHERE status IN ('pending', 'parsed', 'error');

  -- Stejná tolerance a stejný výpočet konce rezervace jako lib/vycepyVenku.ts
  -- (TOLERANCE_DNI = 1 → „po termínu" od 2. dne po konci rezervace).
  SELECT count(*), coalesce(sum(kauce_czk), 0)
  INTO v_vycepy_po_terminu, v_kauce_czk
  FROM vycepy_rezervace
  WHERE vraceno = false
    AND coalesce(datum_do, datum_od) <= current_date - interval '2 days';

  -- Není co hlásit → neposílat prázdný push každé ráno naprázdno.
  IF v_whatsapp_cekajici = 0 AND v_vycepy_po_terminu = 0 THEN
    RETURN;
  END IF;

  IF v_whatsapp_cekajici > 0 THEN
    v_radky := v_radky || (v_whatsapp_cekajici::text || 'x WhatsApp objednávka čeká na schválení');
  END IF;
  IF v_vycepy_po_terminu > 0 THEN
    v_radky := v_radky || (v_vycepy_po_terminu::text || 'x výčep po termínu (kauce ' || v_kauce_czk::text || ' Kč)');
  END IF;
  v_telo := array_to_string(v_radky, ' · ');

  PERFORM net.http_post(
    url := 'https://sasqexjadvlqyticxwja.supabase.co/functions/v1/posli-push',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'X-Internal-Cron-Secret', v_secret
    ),
    body := jsonb_build_object(
      'titulek', 'Ranní souhrn',
      'telo', v_telo,
      'stranka', CASE WHEN v_whatsapp_cekajici > 0 THEN 'orders' ELSE 'vycepy' END,
      'tag', 'ranni-souhrn'
    )
  );
END;
$$;

-- 7:00 v Česku je v UTC 5:00 (letní čas, CEST) nebo 6:00 (zimní, CET) —
-- 5:00 UTC dává v zimě 6:00 místního času, což je ještě dřív, ne později,
-- takže se nikdy nepošle pozdě. Přesné zarovnání na letní/zimní čas by
-- vyžadovalo `AT TIME ZONE 'Europe/Prague'` v cron výrazu, což pg_cron
-- nepodporuje — pevná hodina je stejný kompromis jako u monthly-tank-close.
SELECT cron.schedule(
  'ranni-souhrn-push',
  '0 5 * * *',
  $$SELECT public.posli_ranni_souhrn();$$
);

COMMENT ON FUNCTION public.posli_ranni_souhrn() IS
  'Denní push: kolik WhatsApp objednávek čeká na schválení + kolik výčepů je po termínu. Viz docs/30-navrhu-2026-09-10.md body 16-17.';

sql.20261230030000_merch_items.sql:
-- Sklad reklamních předmětů a merche (MarketingMerchInventory).
--
-- Obrazovka (záložka "Merch" ve Skladu) vypadala hotová — formulář,
-- rychlá úprava množství, upozornění na docházející zásobu — ale
-- neukládala vůbec nic, ani do localStorage. Každá změna zmizela při
-- obnovení stránky a dvě zařízení viděla dvě různá čísla, protože
-- každé mělo jen svůj vlastní vymyšlený počáteční stav (`DEFAULT_MERCH`
-- v komponentě). Nalezeno 10. 9. 2026 (docs/50-navrhu-2026-09-10-treti.md,
-- bod 4).
--
-- Stejný jednoduchý vzor jako obal_nakupy (20261228000000): žádné role
-- navíc, kdokoliv přihlášený smí číst i zapisovat.

CREATE TABLE IF NOT EXISTS public.merch_items (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  category text NOT NULL DEFAULT 'doplnky',
  stock_qty numeric NOT NULL DEFAULT 0,
  min_alert_qty numeric NOT NULL DEFAULT 0,
  unit_cost_kic numeric NOT NULL DEFAULT 0,
  sell_price_kic numeric,
  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

ALTER TABLE public.merch_items ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "auth_read_merch_items" ON public.merch_items;
CREATE POLICY "auth_read_merch_items" ON public.merch_items
  FOR SELECT TO authenticated USING (true);
DROP POLICY IF EXISTS "auth_insert_merch_items" ON public.merch_items;
CREATE POLICY "auth_insert_merch_items" ON public.merch_items
  FOR INSERT TO authenticated WITH CHECK (true);
DROP POLICY IF EXISTS "auth_update_merch_items" ON public.merch_items;
CREATE POLICY "auth_update_merch_items" ON public.merch_items
  FOR UPDATE TO authenticated USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS "auth_delete_merch_items" ON public.merch_items;
CREATE POLICY "auth_delete_merch_items" ON public.merch_items
  FOR DELETE TO authenticated USING (true);

-- Realtime, ať se zápis z jednoho telefonu objeví na druhém.
DO $$
BEGIN
  ALTER PUBLICATION supabase_realtime ADD TABLE public.merch_items;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'merch_items už v publikaci: %', SQLERRM;
END $$;

sql.20261230040000_festival_equipment.sql:
-- Festivalové vybavení — půjčky chladičů, stanů, narážečů (FestivalEquipmentTracker).
--
-- Stejný problém jako merch_items (migrace 20261230030000): obrazovka
-- (záložka "Festival" ve Skladu) vypadala hotová — půjčení, kauce, vrácení
-- — ale neukládala vůbec nic. U vybavení půjčovaného v kaucích za tisíce
-- korun je to horší než u merche: appka se tvářila, že eviduje, kdo má
-- co a kolik kauce leží venku, a ve skutečnosti to zapomněla při
-- obnovení stránky. Nalezeno 10. 9. 2026
-- (docs/50-navrhu-2026-09-10-treti.md, bod 5).
--
-- Přidán i krok "kauce vrácena" (deposit_returned) při vrácení vybavení —
-- v původní verzi vrácení vybavení kauci rovnou "zapomnělo", takže nešlo
-- zpětně dohledat, jestli se peníze skutečně vrátily.

CREATE TABLE IF NOT EXISTS public.festival_equipment (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  category text NOT NULL DEFAULT 'chlazeni',
  serial_code text NOT NULL DEFAULT '',
  status text NOT NULL DEFAULT 'available', -- 'available' | 'borrowed' | 'maintenance'
  borrower_name text,
  borrower_phone text,
  event_name text,
  borrowed_at date,
  expected_return_at date,
  deposit_kic numeric,
  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

-- Historie půjček — jinak se přepsáním "borrowed" -> "available" ztratí,
-- kdo si co půjčil a kdy/jestli se kauce vrátila (na rozdíl od aktuálního
-- stavu v festival_equipment, který drží jen POSLEDNÍ/aktuální půjčku).
CREATE TABLE IF NOT EXISTS public.festival_equipment_loans (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  equipment_id uuid NOT NULL REFERENCES public.festival_equipment(id) ON DELETE CASCADE,
  borrower_name text NOT NULL,
  borrower_phone text,
  event_name text,
  borrowed_at date NOT NULL,
  expected_return_at date,
  returned_at date,
  deposit_kic numeric,
  deposit_returned boolean NOT NULL DEFAULT false,
  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at timestamptz DEFAULT now()
);

CREATE INDEX IF NOT EXISTS festival_equipment_loans_equipment_idx
  ON public.festival_equipment_loans (equipment_id, borrowed_at DESC);

ALTER TABLE public.festival_equipment ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.festival_equipment_loans ENABLE ROW LEVEL SECURITY;

